-- This migration changes only shared reference metadata; custom family rows and numeric nutrients_json remain intact.

ALTER TABLE public.food_library_items
  ADD COLUMN icon VARCHAR(32) NOT NULL DEFAULT '🍽️',
  ADD COLUMN food_group VARCHAR(50),
  ADD COLUMN recommended_from_month INTEGER,
  ADD COLUMN recommended_to_month INTEGER,
  ADD COLUMN exact_month_evidence BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN guidance TEXT,
  ADD COLUMN is_common_allergen BOOLEAN,
  ADD COLUMN allergen_introduction_guidance TEXT,
  ADD COLUMN high_risk_infant_needs_medical_advice BOOLEAN,
  ADD COLUMN choking_risk BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN choking_notes TEXT,
  ADD COLUMN preparation_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN avoid_before_months INTEGER,
  ADD COLUMN nutrition_highlights_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN texture_by_age_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN notes TEXT,
  ADD COLUMN source_refs_json JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN data_source_as_of VARCHAR(10),
  ADD COLUMN data_source_scope VARCHAR(32),
  ADD COLUMN data_source_evidence_conflict BOOLEAN,
  ADD COLUMN catalog_order INTEGER;

ALTER TABLE public.food_library_items
  ADD CONSTRAINT food_library_items_recommended_from_month_check
    CHECK (recommended_from_month IS NULL OR recommended_from_month BETWEEN 0 AND 120),
  ADD CONSTRAINT food_library_items_recommended_to_month_check
    CHECK (recommended_to_month IS NULL OR recommended_to_month BETWEEN 0 AND 120),
  ADD CONSTRAINT food_library_items_avoid_before_months_check
    CHECK (avoid_before_months IS NULL OR avoid_before_months BETWEEN 0 AND 120),
  ADD CONSTRAINT food_library_items_catalog_order_check
    CHECK (catalog_order IS NULL OR catalog_order BETWEEN 1 AND 45);

ALTER TABLE public.family_food_statuses
  ADD COLUMN first_added_date VARCHAR(10),
  ADD COLUMN acceptance INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN version INTEGER NOT NULL DEFAULT 1;

ALTER TABLE public.family_food_statuses
  ADD CONSTRAINT family_food_statuses_first_added_date_check
    CHECK (first_added_date IS NULL OR first_added_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'),
  ADD CONSTRAINT family_food_statuses_acceptance_check
    CHECK (acceptance BETWEEN 0 AND 5),
  ADD CONSTRAINT family_food_statuses_version_check
    CHECK (version >= 1);

-- Rehydrate the retained promotion fields into the active family projection.
UPDATE public.family_food_statuses
SET tried = CASE WHEN legacy_status IN ('tried','to_try') THEN legacy_status='tried' ELSE tried END,
    first_added_date = legacy_first_added_date,
    acceptance = COALESCE(legacy_acceptance, acceptance)
WHERE legacy_status IS NOT NULL OR legacy_first_added_date IS NOT NULL OR legacy_acceptance IS NOT NULL;

